Functions.Things_GetThingPos:
long Things_GetThingPos(NODE *List, DWORD ID, LONG Type)
{
	MAPTHING	*Thing;

	for (Thing = (MAPTHING *)List->next; Thing != 0; Thing = (MAPTHING *)Thing->node.next)
		{
		if (Thing->id == ID)
			{
			switch(Type)
				{
				case 0:	return(Thing->x);
				case 1:	return(Thing->y);
				}
			}
		}

	return(-1);
}

Functions.RectEx_GetRectLocation:
WORD RectEx_GetRectLocation(NODE *RectList, UINT RectID, UINT What)
{
	NODE	*List;
	LONG	 X,Y;

	for (List = RectList->next; List != 0; List = List->next)
		{
		if (((MAPRECTEX *)List)->id == RectID)
			{
			X = ((MAPRECTEX *)List)->rect.x1;
			Y = ((MAPRECTEX *)List)->rect.y1;
			if (!What) return((WORD)X);
			else return((WORD)Y);
			}
		}

	return(0);
}

Functions.RectEx_GetGateAtMapPos:
int RectEx_GetGateAtMapPos(LONG X, LONG Y)
{
	MAPRECTEX	*Gate;

	for (Gate = (MAPRECTEX *)MapGates.next; Gate != 0; Gate = (MAPRECTEX *)Gate->node.next)
		{
		if (Gate->rect.x1 != X) continue;
		if (Gate->rect.y1 != Y) continue;
		return(Gate->id);
		}

	return(0);
}

Functions.List_AddEntry:
void List_AddEntry(NODE *NewEntry, NODE *EntryList)
{
	NODE *List;

	for (List = EntryList; List->next != 0; List = List->next);

	List->next = NewEntry;
	NewEntry->prev = List;
	NewEntry->next = NULL;
	return;
}
